/**
 * Промпт розпізнавання сторінки рукопису (WriterScan).
 *
 * Навмисно ПРОТИЛЕЖНИЙ «Тексту за фото» (server/textFromImagePrompt.ts):
 * там модель — співавтор, який пише сцену за мотивами зображення; тут вона
 * — друкарка, яка переписує рівно те, що бачить. Жодного переказу, жодних
 * виправлень стилю чи орфографії автора: інакше автор не впізнає власний
 * рукопис і не зможе довіряти сканеру.
 *
 * Чиста функція без стану — щоб перевірити тестом без мережі.
 */

export interface ScanOcrPromptOptions {
  /** Мова підказкою (не примусом): рукопис може змішувати мови. */
  languageHint?: string;
}

export function scanOcrSystemInstruction(): string {
  return [
    'Ти — точний засіб розпізнавання тексту (OCR) для сторінок рукописів і книг.',
    'Переписуй ДОСЛІВНО весь текст, який видно на зображенні, у порядку читання.',
    'Не перекладай, не переказуй, не виправляй орфографію чи стиль, не додавай нічого від себе.',
    'Зберігай поділ на абзаци: між абзацами — один порожній рядок.',
    'Переноси слів у кінці рядка зʼєднуй у ціле слово; звичайні переноси рядків усередині абзацу прибирай.',
    'Слово, яке неможливо прочитати, познач як [нерозбірливо].',
    'Колонтитули, номери сторінок і поля з позначками пропускай, якщо вони явно не є частиною тексту.',
    'Якщо тексту на зображенні немає — поверни порожню відповідь.',
    'Відповідай лише самим текстом, без пояснень, лапок і розмітки Markdown.',
  ].join('\n');
}

export function buildScanOcrPrompt(opts: ScanOcrPromptOptions = {}): string {
  const lang = String(opts.languageHint || 'uk').trim();
  const langLine =
    lang === 'uk'
      ? 'Очікувана мова тексту — українська (можуть траплятися інші мови — переписуй їх як є).'
      : `Очікувана мова тексту — ${lang} (інші мови переписуй як є).`;
  return ['Розпізнай текст на цьому фото сторінки.', langLine].join('\n');
}

/**
 * Прибирання відповіді моделі. Моделі інколи загортають результат у ```,
 * додають «Ось текст:» або лапки — автору в редакторі це не потрібно.
 */
export function cleanOcrText(raw: string): string {
  let text = String(raw || '').replace(/\r\n/g, '\n').trim();
  const fenced = text.match(/^```[a-zA-Z]*\n([\s\S]*?)\n```$/);
  if (fenced) text = fenced[1].trim();
  text = text.replace(/^(ось|here is|here's)[^\n]{0,40}:\s*\n/i, '');
  // Три й більше порожніх рядків поспіль — це один розрив абзацу.
  text = text.replace(/\n{3,}/g, '\n\n');
  return text.trim();
}
